{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Logging is not enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket 'admin_dashboard' does not have logging enabled, which can make it difficult to track access and changes to the bucket."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket does not have versioning enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket 'admin_dashboard' does not have versioning enabled, which means that if objects are accidentally deleted or overwritten, they cannot be recovered."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket does not have cross-region replication enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "LOW",
      "explanation": "The S3 bucket 'admin_dashboard' does not have cross-region replication enabled, which means that data is not replicated to another region for disaster recovery purposes."
    },
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 Bucket does not have MFA Delete enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "The S3 bucket 'admin_dashboard' does not have MFA Delete enabled, which means that objects can be deleted without additional authentication."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "admin_dashboard" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}"
  versioning {
    enabled = true
    mfa_delete = true
  }
  logging {
    target_bucket = "${aws_s3_bucket.admin_dashboard.id}-logs"
    target_prefix = "/logs/"
  }
  replication_configuration {
    role = aws_iam_role.replication.arn
    rules {
      id     = "replication-rule"
      status = "Enabled"
      destination {
        bucket = "arn:aws:s3:::smart-city-parking-management-system-s3-admin-dashboard-replica-${random_string.bucket_suffix.result}"
      }
    }
  }
}

resource "aws_s3_bucket" "admin_dashboard_logs" {
  bucket = "${aws_s3_bucket.admin_dashboard.id}-logs"
}

resource "aws_iam_role" "replication" {
  name        = "s3-replication-role"
  description = "S3 replication role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}",
  "fix_summary": "Enabled S3 bucket versioning with MFA delete, added logging to a new bucket, and configured cross-region replication to another bucket, along with creating the necessary logging bucket and replication IAM role."
}
